// eslint-disable-next-line import/no-unresolved
import Tracer from '../common/Tracer';
import MaskRenderer from './MaskRenderer/index';

class MaskTracer extends Tracer {
  getRendererClass() {
    return MaskRenderer;
  }

  init() {
    super.init();
    this.maxBits = 0;
    this.binaryData = 0;
    this.maskData = 0;
    this.highlight = [];
    this.addBase4 = false;
    this.radix = 2;
    this.pointerStatus = null;
  }

  setPointerStatus(status) {
    this.pointerStatus = status;
  }

  setAddBase4(b) {
    this.addBase4 = b;
  }

  // Overlay only: 4 also shows base 4 digits, two bits per digit;
  // 10 shows the key's decimal digits instead of bits.
  setRadix(radix) {
    this.radix = radix;
  }

  setMaxBits(bits) {
    this.maxBits = bits;
  }

  setBinary(data) {
    this.binaryData = data;
  }

  setMask(maskDecimal, maskIndex) {
    this.maskData = maskDecimal;
    this.highlight = typeof maskIndex === "number" ? [maskIndex] : maskIndex;
  }
}

export default MaskTracer;
