import React from 'react';
import Renderer from '../../common/Renderer';
import styles from './MaskRenderer.module.scss';
import BinaryRenderer from '../BinaryRenderer';

class MaskRenderer extends Renderer {
  constructor(props) {
    super(props)
    this.centerX = 0;
    this.centerY = 0;
    this.zoom = 100;
    this.elementRef = React.createRef();
    this.togglePan(true);
    this.toggleZoom(true);
  }

  // display key in decimal, base 4 (optional) and binary plus
  // mask in binary; some (non-decimal) digits highlighted
  renderData() {
    const {
      binaryData,
      maskData,
      maxBits,
      highlight,
      addBase4,
      overlay,
      pointerStatus,
      radix = 2,
    } = this.props.data;
    const status = pointerStatus != null && (
      <div className={styles.pointerStatus} role="status" aria-live="polite">
        {pointerStatus}
      </div>
    );
    if (overlay && radix === 10) {
      // Decimal trie: keys keep their own length, the mask is the place
      // value of the highlighted digit.
      const digit = Math.floor(binaryData / maskData) % 10;
      return (
        <div className={styles.overlayContainer}>
          <BinaryRenderer
            header={"Current key"}
            data={binaryData}
            highlight={highlight}
            base={10}
            compact={true}
          />
          <BinaryRenderer
            header={"Place value"}
            data={maskData}
            highlight={highlight}
            base={10}
            compact={true}
          />
          <div className={styles.decision}>
            DIGIT {digit} &rarr; CHILD {digit}
          </div>
          {status}
        </div>
      );
    }
    if (overlay) {
      // Trie and DST share this panel: group long keys into nibbles so
      // they wrap the same way instead of overflowing.
      const groupSize = maxBits > 12 ? 4 : 0;
      const selectedBit = (binaryData & maskData) === 0 ? 0 : 1;
      const direction = selectedBit === 0 ? 'LEFT' : 'RIGHT';
      // Base 4: digit i covers bits 2i+1 and 2i (avoid & past bit 30).
      const digitIndex = Math.floor(Math.min(...highlight) / 2);
      const selectedDigit = Math.floor(binaryData / 4 ** digitIndex) % 4;
      return (
        <div className={styles.overlayContainer}>
          <BinaryRenderer
            header={"Current key"}
            data={binaryData}
            highlight={[]}
            base={10}
            compact={true}
          />
          {radix === 4 && (
            <BinaryRenderer
              header={"Base 4"}
              data={binaryData}
              maxBits={maxBits / 2}
              highlight={[digitIndex]}
              base={4}
              compact={true}
              groupSize={groupSize / 2}
            />
          )}
          <BinaryRenderer
            header={"Binary"}
            data={binaryData}
            maxBits={maxBits}
            highlight={highlight}
            compact={true}
            groupSize={groupSize}
          />
          <BinaryRenderer
            header={"Mask"}
            data={maskData}
            maxBits={maxBits}
            highlight={highlight}
            compact={true}
            groupSize={groupSize}
          />
          <div className={styles.decision}>
            {radix === 4
              ? <>DIGIT {selectedDigit} &rarr; BRANCH {selectedDigit}</>
              : <>BIT {selectedBit} &rarr; {direction}</>}
          </div>
          {status}
        </div>
      );
    }
    let extra = <div/>;
    if (addBase4) {
       console.log([highlight,highlight.map((b) => Math.trunc(parseInt(b)/2))]);
        extra =
            <BinaryRenderer
              header={"Base 4"}
              emphasise={true}
              data={binaryData}
              maxBits={maxBits/2}
              highlight={highlight.map((b) => Math.trunc(parseInt(b)/2))}
              base={4}
            />
    }
    return (
      <div className={styles.container}>
        <BinaryRenderer
          header={"Decimal"}
          data={binaryData}
          highlight={[]}
          base={10}
        />
        {extra}
        <BinaryRenderer
          header={"Binary"}
          emphasise={!addBase4}
          data={binaryData}
          maxBits={maxBits}
          highlight={highlight}
        />
        <BinaryRenderer
          header={"Mask"}
          data={maskData}
          maxBits={maxBits}
          highlight={highlight}
        />
      </div>
    );
  }
}

export default MaskRenderer;
